/* @lc app=leetcode id=3464 lang=kotlin */ class Solution { fun pos(side: Int, p: IntArray): Long = if (p[1] == 0) p[0].toLong() else if (p[0] == side) side + p[1].toLong() else if (p[1] == side) 3L * side - p[0] else 4L * side - p[1] fun man(a: IntArray, b: IntArray): Long = Math.abs(a[0].toLong() - b[0]) + Math.abs(a[1].toLong() - b[1]) fun ok(ps: List<IntArray>, k: Int, d: Long): Boolean = ps.size.let { n -> IntArray(2 * n + 1) { 2 * n }.also { nxt -> (0 until 2 * n).fold(0) { j, i -> generateSequence(maxOf(j, i + 1)) { jj -> if (jj < 2 * n && man(ps[i % n], ps[jj % n]) < d) jj + 1 else null }.last().also { nxt[i] = it } } }.let { nxt -> (0 until n).any { s -> (1 until k).fold(s) { cur, _ -> nxt[cur] }.let { cur -> cur < s + n && man(ps[cur % n], ps[s]) >= d } } } } fun maxDistance(side: Int, points: Array<IntArray>, k: Int): Int = points.sortedBy { pos(side, it) }.let { ps -> generateSequence(0L to 2L * side) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { mid -> if (ok(ps, k, mid)) mid to hi else lo to mid - 1 } }.last().first.toInt() } }